import {useNavigate} from "react-router-dom";
import {useLocation} from "react-router-dom";

export default function Badge() {
    const navigate = useNavigate();
    const location = useLocation();
    const mpospiritAppsPaths = [
        "/apps", 
        "/apps/cogio", 
        "/apps/cogio/privacy-policy",
        "/apps/cogio/license",
        "/apps/cogio/feedback",
        "/apps/cogio/bug-report",
        "/apps/cogio/support",
        "/apps/fundatio",
        "/apps/fundatio/privacy-policy",
        "/apps/fundatio/license",
        "/apps/fundatio/feedback",
        "/apps/fundatio/bug-report",
        "/apps/fundatio/support",
    ];

    const nameStyle = {
        marginTop: "10px",
        marginBottom: 0,
        cursor: "pointer",
    }
    const nicknameStyle = {
        fontStyle: "italic",
        marginTop: "-7px",
        marginBottom: "20px",
        cursor: "pointer",
    }

    return (
        <div className="d-flex flex-column align-items-end">
            <h1 onClick={() => navigate('/')} style={nameStyle}>
                {mpospiritAppsPaths.includes(location.pathname) ? "mpospirit.apps" : "Çağrı Gökpunar"}
            </h1>
            <p onClick={() => navigate('/')} style={nicknameStyle}>
                {mpospiritAppsPaths.includes(location.pathname) ? "by Çağrı Gökpunar" : "mpospirit"}
            </p>
        </div>
    )
}